		#region Update PK Collections
		
        public void SetPKValues()
        {
                if (colTblExecutionContractRecords != null)
                {
                    foreach (SweetSoft.QLDA.DataAccess.TblExecutionContract item in colTblExecutionContractRecords)
                    {
                        if (item.CustomerId != Id)
                        {
                            item.CustomerId = Id;
                        }
                    }
               }
		
                if (colTblProjectRecords != null)
                {
                    foreach (SweetSoft.QLDA.DataAccess.TblProject item in colTblProjectRecords)
                    {
                        if (item.CustomerId != Id)
                        {
                            item.CustomerId = Id;
                        }
                    }
               }
		}
        #endregion
    
        #region Deep Save
		
        public void DeepSave()
        {
            Save();
            
                if (colTblExecutionContractRecords != null)
                {
                    colTblExecutionContractRecords.SaveAll();
               }
		
                if (colTblProjectRecords != null)
                {
                    colTblProjectRecords.SaveAll();
               }
		}
        #endregion
